{"command": "python3 - << 'EOF'
import re, html as H
raw = open('index.html').read()
text = re.sub(r'<script.*?</script>', '', raw, flags=re.S)
# collect (title, href) pairs
pairs = re.findall(r'<a href="([^"]+)"[^>]*>(.*?)</a>', text, flags=re.S)
def clean(t):
    t = H.unescape(re.sub(r'<[^>]+>', '', t))
    return re.sub(r'\s+', ' ', t).strip()
targets = ['candy', 'sophie', 'draft day', 'boys from brazil', 'puncture', 'golden pond', 'detachment', 'belle et la bete', 'beauty and the beast', 'knight of cups', 'midnight sun']
seen = set()
for href, t in pairs:
    c = clean(t)
    lc = c.lower()
    for tg in targets:
        if tg in lc and c not in seen:
            seen.add(c)
            print(f'[{tg}] {c}  ->  {href}')
            break
EOF"}

