        return titles[0].strip() if titles else '?', ogs[:2], posts[:5], len(html)
    except Exception as e:
        return f'ERROR {e}', [], [], 0

queries = ['detachment', 'detachment-2011', 'puncture', 'puncture-2011', 'draft-day', 'sophies-choice', 'sophie%27s-choice',
