def yt_search(query, n=8):
    h = get('https://www.youtube.com/results?search_query=' + urllib.parse.quote(query)).decode('utf-8','ignore')
    m = re.search(r'var ytInitialData = (\{.*?\});</script>', h, flags=re.S)
    if not m: return []
    d = json.loads(m.group(1))
    out = []
    def walk(o):
        if isinstance(o, dict):
            if 'videoRenderer' in o:
                vr = o['videoRenderer']
                vid = vr.get('videoId')
                title = ''.join(r.get('text','') for r in vr.get('title',{}).get('runs',[]))
                ch = ''.join(r.get('text','') for r in vr.get('ownerText',{}).get('runs',[]))
